"""Certified hinge fitting: recover the admissible slope interval, not a point estimate.

A hinge budget law is H(j) = max(floor, base + slope * j).  Measured points that sit
on the floor contribute only the inequality base + slope*j <= floor, while points
strictly above the floor contribute equalities.  Consequently a grid that begins below
the kink bounds the slope from below without identifying it, and the honest output of
a fit is an interval of slopes together with the base each one forces.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple


def hinge(floor: int, base: int, slope: int, j: int) -> int:
    return max(floor, base + slope * j)


def admissible_fits(floor: int, data: Sequence[int],
                    max_slope: int = 64) -> List[Tuple[int, int]]:
    """All (base, slope) in N^2 with max(floor, base + slope*j) == data[j] for all j.

    Cost: O(max_slope * len(data)) -- for each candidate slope the base is determined
    by any point strictly above the floor, and the remaining points are verified.
    """
    fits: List[Tuple[int, int]] = []
    lifted = [(j, v) for j, v in enumerate(data) if v > floor]
    for slope in range(max_slope + 1):
        if lifted:
            j0, v0 = lifted[0]
            base = v0 - slope * j0
            if base < 0:
                continue
            candidates = [base]
        else:
            candidates = list(range(0, floor + 1))
        for base in candidates:
            if all(hinge(floor, base, slope, j) == v for j, v in enumerate(data)):
                fits.append((base, slope))
    return fits


def slope_interval(floor: int, data: Sequence[int]) -> Optional[Tuple[int, int]]:
    """Least and greatest admissible slope, or None if no hinge fits the data."""
    fits = admissible_fits(floor, data)
    if not fits:
        return None
    slopes = [s for _, s in fits]
    return min(slopes), max(slopes)


def discriminating_point(floor: int, data: Sequence[int],
                         horizon: int = 8) -> Optional[Tuple[int, Dict[int, int]]]:
    """Smallest j beyond the data at which the admissible fits disagree.

    Returns (j, {slope: predicted keys}) or None if they never separate below horizon.
    """
    fits = admissible_fits(floor, data)
    for j in range(len(data), horizon + 1):
        preds = {s: hinge(floor, b, s, j) for b, s in fits}
        if len(set(preds.values())) > 1:
            return j, preds
    return None


if __name__ == "__main__":
    measured = [16, 16, 18]                  # large model at contexts 512, 1024, 2048
    fits = admissible_fits(16, measured)
    print("admissible (base, slope):", fits)
    print("slope interval:", slope_interval(16, measured))
    j, preds = discriminating_point(16, measured)   # type: ignore[misc]
    print(f"fits first disagree at j = {j} (context {512 * 2 ** j}):")
    for s in sorted(preds):
        print(f"   slope {s}: {preds[s]} keys")
